#include "PluginProcessor.h"
namespace {
const char* memoIds[]={"tapeSpeed","track1","track2","track3","track4","volume","tapeLoopIn","tapeLoopOut","tapeOverdub","tapeLoop","eqLow","eqMid","eqHigh","eqMix","masterDrive","masterEcho","masterDelayTime","masterFeedback","inputGain","tapeRecordGain","clickVolume"};
}
bool PocketProcessor::tapeEdit(const juce::String& action,bool shifted,juce::String& error) {
    if(state.getRawParameterValue("tapePlay")->load()>.5f||state.getRawParameterValue("tapeRecord")->load()>.5f||tapeSpool.load()!=0){error="Stop tape before editing. Recorded audio is kept until the operation succeeds.";return false;}
    const int track=int(state.getRawParameterValue("tapeTrack")->load());const double seconds=4<<int(state.getRawParameterValue("tapeLength")->load());bool ok=false;
    if(action=="sampler") {pocket::Sample data;{const juce::ScopedLock lock(getCallbackLock());data.frames=tape.clipboardMono();data.rate=tape.getRate();}if(data.frames.empty()){error="Lift a take from tape first.";return false;}publishSamplePreview(data);const int size=int(data.frames.size());{const juce::ScopedLock lock(getCallbackLock());engine.swapSample(data);sampleFrames.store(size);}for(auto value:{std::pair{"engine",3.f},{"tone",0.f},{"color",1.f},{"sampleRoot",60.f}}){auto* p=state.getParameter(value.first);p->setValueNotifyingHost(p->convertTo0to1(value.second));}setSelectedSound({});currentFactoryPreset.store(-1);currentUserPreset.store(-1);requestPanic();return true;}
    {const juce::ScopedLock lock(getCallbackLock());tape.finishRecording();tape.setRegion(state.getRawParameterValue("tapeLoop")->load()>.5f,state.getRawParameterValue("tapeLoopIn")->load(),state.getRawParameterValue("tapeLoopOut")->load());
        if(action=="split")ok=tape.split(track,shifted,seconds);
        else if(action=="lift")ok=tape.lift(track,shifted,seconds,state.getRawParameterValue("tapeLoop")->load()>.5f);
        else if(action=="drop")ok=tape.drop(track,seconds);
        else if(action=="undo")ok=tape.undo();else if(action=="clear"){tape.clear(track);ok=true;}
        tapePosition.store(float(tape.getPosition()));}
    if(ok&&action=="lift")clipboardKind.store(1);
    if(!ok)error=action=="drop"?"The tape clipboard is empty or the head is at the end.":action=="undo"?"There is no tape edit to undo.":"No take boundary or audio range is available here.";return ok;
}
void PocketProcessor::tapeMemo(int slot,bool store) {if(slot<0||slot>1)return;if(store){const juce::ScopedLock lock(libraryStateLock);for(int i=0;i<21;++i)tapeMemos[size_t(slot)][size_t(i)]=state.getRawParameterValue(memoIds[i])->load();memoSaved[size_t(slot)]=true;}else {std::array<float,21> values;{const juce::ScopedLock lock(libraryStateLock);if(!memoSaved[size_t(slot)])return;values=tapeMemos[size_t(slot)];}for(int i=0;i<21;++i){auto* p=state.getParameter(memoIds[i]);p->beginChangeGesture();p->setValueNotifyingHost(p->convertTo0to1(values[size_t(i)]));p->endChangeGesture();}}}
juce::ValueTree PocketProcessor::tapeEditSnapshot() {juce::ValueTree tree("TapeEdits");{const juce::ScopedLock lock(getCallbackLock());if(state.getRawParameterValue("tapeRecord")->load()<.5f)tape.finishRecording();const auto& markers=tape.getCuts();for(int track=0;track<4;++track)for(double seconds:markers[size_t(track)]){juce::ValueTree cut("Cut");cut.setProperty("track",track,nullptr);cut.setProperty("seconds",seconds,nullptr);tree.addChild(cut,-1,nullptr);}}{const juce::ScopedLock lock(libraryStateLock);for(int slot=0;slot<2;++slot)if(memoSaved[size_t(slot)]){juce::ValueTree memo("Memo");memo.setProperty("slot",slot,nullptr);for(int i=0;i<21;++i)memo.setProperty(memoIds[i],tapeMemos[size_t(slot)][size_t(i)],nullptr);tree.addChild(memo,-1,nullptr);}}return tree;}
void PocketProcessor::restoreTapeEdits(const juce::ValueTree& tree){std::array<std::vector<double>,4> cuts;{const juce::ScopedLock lock(libraryStateLock);memoSaved.fill(false);for(const auto& child:tree){if(child.hasType("Cut")){int track=int(child.getProperty("track",-1));double seconds=double(child.getProperty("seconds"));if(track>=0&&track<4&&std::isfinite(seconds)&&seconds>0&&seconds<16&&cuts[size_t(track)].size()<1024)cuts[size_t(track)].push_back(seconds);}else if(child.hasType("Memo")){int slot=int(child.getProperty("slot",-1));if(slot>=0&&slot<2){for(int i=0;i<21;++i)tapeMemos[size_t(slot)][size_t(i)]=float(child.getProperty(memoIds[i],0));memoSaved[size_t(slot)]=true;}}}}const juce::ScopedLock lock(getCallbackLock());tape.setCuts(std::move(cuts));}
std::pair<float,float> PocketProcessor::currentTapeTake(){const juce::ScopedLock lock(getCallbackLock());auto range=tape.take(int(state.getRawParameterValue("tapeTrack")->load()),4<<int(state.getRawParameterValue("tapeLength")->load()));return {float(range.first/tape.getRate()),float(range.second/tape.getRate())};}
bool PocketProcessor::slideTape(double delta,juce::String& error){if(state.getRawParameterValue("tapePlay")->load()>.5f||state.getRawParameterValue("tapeRecord")->load()>.5f){error="Stop tape before sliding a take.";return false;}const juce::ScopedLock lock(getCallbackLock());if(!tape.slide(int(state.getRawParameterValue("tapeTrack")->load()),delta,4<<int(state.getRawParameterValue("tapeLength")->load()))){error="The take cannot move past the tape edge or overlap another take.";return false;}tapePosition.store(float(tape.getPosition()));return true;}
bool PocketProcessor::exportMix(const juce::File& file,juce::String& error){juce::MemoryBlock snapshot;getStateInformation(snapshot);auto render=std::make_unique<PocketProcessor>(juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("pocket-offline-render"));render->setStateInformation(snapshot.getData(),int(snapshot.getSize()));double sr;{const juce::ScopedLock lock(getCallbackLock());sr=rate;}for(const char* id:{"sequencer","tapeRecord","metronome","inputMonitor"})render->state.getParameter(id)->setValueNotifyingHost(0);render->state.getParameter("tapePlay")->setValueNotifyingHost(1);render->prepareToPlay(sr,256);const int frames=int(sr*(4<<int(state.getRawParameterValue("tapeLength")->load())));auto stream=file.createOutputStream();if(!stream){error="Cannot create the stereo WAV file.";return false;}stream->setPosition(0);stream->truncate();juce::WavAudioFormat wav;std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(stream.get(),sr,2,24,{},0));if(!writer){error="Cannot create the WAV writer.";return false;}stream.release();juce::AudioBuffer<float> block(2,256);juce::MidiBuffer midi;for(int done=0;done<frames;done+=256){const int n=std::min(256,frames-done);block.setSize(2,n,false,false,true);block.clear();render->processBlock(block,midi);if(!writer->writeFromAudioSampleBuffer(block,0,n)){error="Could not write the complete stereo mix.";return false;}}return true;}
